using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckLimbo.Editor {
public static class LimboAuthoring {
 public const string Folder="TruckLimbo",Scene="Assets/TruckLimbo/Scenes/TruckLimbo.unity";
 static Material timber,navy,cream,pink,cyan,gold;static PhysicsMaterial ground,wood;
 [MenuItem("Truck Sports/Limbo/Create new tropical festival scene")]
 public static void Create(){if(File.Exists(Scene))throw new InvalidOperationException("Limbo exists; preserve hand-edited scene and use targeted upgrades.");var m=SportsEventAuthoring.Begin<LimboMatch>(Folder);m.setup.count=4;m.option=1;m.NormalizeSetup();for(int i=1;i<m.setup.players.Length;i++)m.setup.players[i].source=LWS.TruckBowling.BowlingSource.AI;ground=SportsEventAuthoring.Contact(Folder,"Festival sand and decking",.8f,.02f);wood=SportsEventAuthoring.Contact(Folder,"Limbo bamboo contact",.45f,.02f);navy=Mat("Festival midnight trim",new Color(.02f,.055f,.085f),.45f);timber=Mat("Natural bamboo",new Color(.42f,.24f,.08f),.16f);cream=Mat("Warm canvas",new Color(.94f,.87f,.65f),.12f);pink=Mat("Festival coral",new Color(.95f,.12f,.4f),.25f);cyan=Mat("Festival lagoon",new Color(.04f,.65f,.75f),.3f);gold=Mat("Festival marigold",new Color(1,.6f,.04f),.2f);
  var sand=Mat("Actual Vista beach sand",Color.white,.06f);var layer=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Sand/Sand_VistaSample.terrainlayer");if(layer==null)throw new InvalidOperationException("Installed Vista beach surface missing");sand.mainTexture=layer.diffuseTexture;sand.mainTextureScale=Vector2.one*20;if(layer.normalMapTexture!=null){sand.SetTexture("_BumpMap",layer.normalMapTexture);sand.EnableKeyword("_NORMALMAP");sand.SetFloat("_BumpScale",.55f);}SportsEventAuthoring.Box("Textured tropical festival sand",new Vector3(0,-.25f,23),new Vector3(90,.5f,105),sand,ground);
  m.racers=new LimboRacer[8];var trucks=new SportsEventTruck[8];for(int i=0;i<8;i++){float x=(i%4-1.5f)*13,z=i/4*42;var t=SportsEventAuthoring.Truck(m,Folder,"Limbo dancer "+(i+1),new Vector3(x,.86f,z-14),i);SportsRallyAuthoring.FitTruck(t);t.motorTorque=5;t.brakeTorque=20;t.maxSpeed=5;t.reverseSpeed=2.2f;t.steerAngle=22;t.body.mass=12;t.body.maxAngularVelocity=7;foreach(var w in t.wheels){w.spring.maxLength=.75f;w.spring.maxForce=170;w.damper.bumpRate=w.damper.reboundRate=35;}
   // Separate the actual cab/exhaust from the low chassis: no invisible full-
   // length roof box behind the cab. NWH keeps its existing wheel contacts.
   foreach(var mesh in t.visuals.GetComponentsInChildren<MeshFilter>(true))if(mesh.name=="Chassis"){var bounds=SportsRallyAuthoring.BoundsIn(mesh,t.transform);t.shape.center=bounds.center;t.shape.size=bounds.size;}
   foreach(var mesh in t.visuals.GetComponentsInChildren<MeshFilter>(true))if(mesh.name=="Cab"||mesh.name=="Exhaust"||mesh.name.StartsWith("MirrorGlass")){var collider=t.gameObject.AddComponent<BoxCollider>();var bounds=SportsRallyAuthoring.BoundsIn(mesh,t.transform);collider.center=bounds.center;collider.size=Vector3.Max(bounds.size,Vector3.one*.025f);collider.sharedMaterial=t.shape.sharedMaterial;}
   var r=t.gameObject.AddComponent<LimboRacer>();r.match=m;r.truck=t;r.slot=i;r.laneCenter=x;r.start=t.transform.position;m.racers[i]=r;trucks[i]=t;r.bar=Bar(r,x,z,m.startHeight);
   SportsEventAuthoring.Box("Inlaid contestant runway",new Vector3(x,.01f,z-3),new Vector3(9,.02f,34),sand,null);for(int side=-1;side<=1;side+=2){var line=SportsEventAuthoring.Box("Festival runway border",new Vector3(x+side*4.8f,.025f,z-3),new Vector3(.10f,.025f,34),i%2==0?pink:cyan,null);for(int n=0;n<5;n++){var stripe=SportsEventAuthoring.Box("Learnable approach reference mark",new Vector3(x+side*3.8f,.04f,z-11+n*2),new Vector3(.55f,.025f,.1f),cream,null);}}
  }
  m.views=SportsRallyAuthoring.Views(m,trucks);m.views.groundOffset=new Vector3(0,4.5f,-10);m.views.groundLookAhead=3;m.views.groundFov=64;m.atmosphere=SportsChaosAuthoring.Weather(m,Folder);m.views.weather=m.atmosphere;m.weatherPresets=SportsWeatherPresetsAuthoring.EnsureCatalog();SportsWeatherRenderingAuthoring.Install(m,Folder);m.feedback.clips=(AudioClip[])LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create().Clone();m.partyMusic=m.gameObject.AddComponent<AudioSource>();m.partyMusic.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDanceOff/Audio/Music/Diesel Disco.wav");m.partyMusic.loop=true;m.partyMusic.playOnAwake=false;m.partyMusic.spatialBlend=0;Dress(m);
  SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);var setup=m.menus.pages[0].transform;var title=setup.Find("Title").GetComponent<TMPro.TMP_Text>();title.rectTransform.anchoredPosition=new Vector2(0,408);title.rectTransform.sizeDelta=new Vector2(1350,60);title.fontSizeMax=44;SportsWeatherPickerAuthoring.Install(m,m.weatherPresets,new Vector2(0,320));foreach(var label in setup.GetComponentsInChildren<TMPro.TMP_Text>(true))if(label.name=="Weather selection label"||label.name=="Weather selection explanation")label.gameObject.SetActive(false);SportsBroadcastAuthoring.ApplyScene();LimboReviewAuthoring.Install(m);SportsEventAuthoring.Save(Folder);Validate();
 }
 static LimboBar Bar(LimboRacer racer,float x,float z,float height){var root=new GameObject("Physical bamboo limbo bar "+racer.slot);root.transform.position=new Vector3(x,height+.075f,z);var body=root.AddComponent<Rigidbody>();body.mass=1.5f;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.solverIterations=16;body.linearDamping=.08f;body.angularDamping=.2f;var collider=root.AddComponent<CapsuleCollider>();collider.direction=0;collider.height=8;collider.radius=.075f;collider.sharedMaterial=wood;var bar=root.AddComponent<LimboBar>();bar.body=body;bar.racer=racer;bar.ledges=new Transform[2];for(int n=0;n<10;n++){var segment=Cylinder("Painted bamboo bar segment",root.transform,new Vector3(-3.6f+n*.8f,0,0),new Vector3(.15f,.8f,.15f),n%3==0?pink:n%3==1?cyan:gold,false);segment.transform.localRotation=Quaternion.Euler(0,0,90);}
  for(int side=-1;side<=1;side+=2){Cylinder("Bamboo limbo upright",null,new Vector3(x+side*4.3f,1.85f,z),new Vector3(.24f,3.7f,.24f),timber,true);Cylinder("Weighted limbo stand foot",null,new Vector3(x+side*4.3f,.08f,z),new Vector3(.9f,.16f,.9f),navy,true);var ledge=SportsEventAuthoring.Box("Adjustable physical bamboo cup",new Vector3(x+side*4.0f,height-.06f,z),new Vector3(.9f,.12f,.45f),timber,wood);bar.ledges[side<0?0:1]=ledge.transform;for(int mark=0;mark<10;mark++)SportsEventAuthoring.Box("Real bar-height measuring band",new Vector3(x+side*4.3f,.9f+mark*.25f,z-.127f),new Vector3(.28f,.025f,.02f),mark%2==0?cream:gold,null);}
  return bar;
 }
 static void Dress(LimboMatch m){var root=new GameObject("Tropical limbo party · actual Vista palms and original bunting").transform;const string palm="Assets/PinwheelStudio/Vista/Personal/Samples/Prefabs/VistaSample_PalmTree.prefab";for(int i=0;i<20;i++){float x=i%2==0?-40:40,z=-20+i/2*10;SportsRallyAuthoring.Prop(root,palm,new Vector3(x,0,z),new Vector3(8,12,8));}
  var pennant=new Mesh{name="Original double-sided cloth pennant"};pennant.vertices=new[]{new Vector3(-1,0,0),new Vector3(1,0,0),new Vector3(0,-1.4f,.06f),new Vector3(0,-1.4f,.06f),new Vector3(1,0,0),new Vector3(-1,0,0)};pennant.triangles=new[]{0,1,2,3,4,5};pennant.RecalculateNormals();AssetDatabase.CreateAsset(pennant,"Assets/TruckLimbo/Materials/Original cloth pennant.asset");for(int row=0;row<2;row++)for(int i=0;i<26;i++){float x=-39+i*3,z=19+row*42;var flag=new GameObject("Original cloth festival pennant").transform;flag.SetParent(root,false);flag.localPosition=new Vector3(x,4+Mathf.Sin(i*.5f)*.3f,z);flag.gameObject.AddComponent<MeshFilter>().sharedMesh=pennant;flag.gameObject.AddComponent<MeshRenderer>().sharedMaterial=i%3==0?pink:i%3==1?cyan:gold;}
  var audience=m.gameObject.AddComponent<LimboAudience>();audience.match=m;var controller=SportsAudienceAuthoring.DanceController(Folder);var prefabs=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/TruckPedestrianPlowing/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).OrderBy(p=>p).ToArray();var actors=new List<Animator>();for(int i=0;i<32;i++){float x=(i%16-7.5f)*4.5f,z=i/16*42+20;actors.Add(SportsAudienceAuthoring.Spawn(AssetDatabase.LoadAssetAtPath<GameObject>(prefabs[i%prefabs.Length]),root,new Vector3(x,0,z),new Vector3(x,0,z-10),controller));}audience.actors=actors.ToArray();
  SportsEventAuthoring.Box("Tropical DJ mixing desk",new Vector3(0,1.1f,26),new Vector3(8,2.2f,2.8f),navy,ground,root);SportsEventAuthoring.Box("Striped DJ desk inset",new Vector3(0,1.2f,24.57f),new Vector3(7.5f,1.6f,.04f),cyan,null,root);var booth=UnityEngine.Object.Instantiate(m.racers[0].truck.visuals.gameObject,root).transform;booth.name="Resident beach DJ · owned truck model";booth.position=new Vector3(0,2.3f,27);booth.rotation=Quaternion.Euler(0,180,0);foreach(var c in booth.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var script in booth.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(script);
  var sign=SportsEventAuthoring.Label("Festival stage title","HOW LOW CAN SIX TONS GO?",new Vector3(0,5,27),.18f,cream.color);sign.transform.rotation=Quaternion.identity;
 }
 static Material Mat(string name,Color color,float smooth)=>SportsEventAuthoring.Mat(Folder,name,color,smooth);
 static GameObject Cylinder(string name,Transform parent,Vector3 position,Vector3 size,Material material,bool collision){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=position;g.transform.localScale=new Vector3(size.x,size.y*.5f,size.z);g.GetComponent<Renderer>().sharedMaterial=material;if(collision)g.GetComponent<Collider>().sharedMaterial=wood;else UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 public static void UpgradeDynamics(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<LimboMatch>();foreach(var r in m.racers)foreach(var w in r.truck.wheels)w.damper.bumpRate=w.damper.reboundRate=35;EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<LimboMatch>();if(m==null||m.racers.Length!=8||m.views.views.Length!=4||m.weatherPresets==null||m.GetComponent<LimboAudience>()==null)throw new InvalidOperationException("Saved Limbo scene references incomplete.");foreach(var r in m.racers)if(r.truck==null||r.bar==null||r.bar.body==null||r.bar.ledges.Length!=2||r.truck.GetComponents<BoxCollider>().Length<3)throw new InvalidOperationException("Limbo needs real NWH truck compound bodies, movable bars and ledges.");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new InvalidOperationException("Limbo requires one audio listener.");Debug.Log("LIMBO_SAVED_VALIDATED eight actual courses / NWH suspension / compound truck hulls / dynamic bars / shared weather");}
}
}
